SELECT dp.id FROM device_point dp JOIN resource_node rn ON rn.id = dp.point_resource_id LEFT JOIN resource_node dev ON dev.id = dp.device_resource_id WHERE dp.tenant_id = #{t} AND rn.code = #{pointCode}
AND dev.code = #{deviceCode}
ORDER BY dp.id LIMIT 1

SELECT rn.code
  FROM device_point dp JOIN resource_node rn ON rn.id = dp.point_resource_id
 WHERE dp.tenant_id = #{t} AND dp.id = #{pointId}

SELECT id FROM experiment_run
 WHERE tenant_id = #{t} AND experiment_id = #{experimentId}
 ORDER BY id DESC LIMIT 1

mapper.update:
UPDATE manifest_placement
   SET position_id = #{positionId}, status = 'assigned', updated_at = now()
 WHERE tenant_id = #{t} AND id = #{placementId}

UPDATE manifest_placement
   SET status = 'verified', verified_by = #{verifiedBy}, verified_at = now(), updated_at = now()
 WHERE tenant_id = #{t} AND id = #{placementId}
